$db   = 'Bob';              // Database name
$user = 'your_username';    // Database username
$pass = 'your_password';    // Database password
$charset = 'utf8mb4';       // Character set

// Data Source Name (DSN)
$dsn = "mysql:host=$host;dbname=$db;charset=$charset";

// PDO options for better security and error handling
$options = [
    PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION, // Enable exceptions
    PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,       // Fetch associative arrays
    PDO::ATTR_EMULATE_PREPARES   => false,                  // Disable emulated prepares
];

try {
    // Establish a connection to the database
    $pdo = new PDO($dsn, $user, $pass, $options);
} catch (PDOException $e) {
    // Handle connection errors (in production, log this instead)
    die("Database connection failed: " . $e->getMessage());
}

// Initialize variables
$field1 = $field2 = "";
$success = $error = "";

// Handle form submission
if ($_SERVER["REQUEST_METHOD"] == "POST") {
    // Sanitize and retrieve POST data
    $field1 = trim($_POST['field1'] ?? '');
