## 3. Using JavaScript's FileReader API to Read the File

Let's create the `script.js` file and add JavaScript code to handle the file reading.

```javascript
// script.js

document.getElementById('csvFileInput')
    .addEventListener('change', function (e) {
        const file = e.target.files[0];

        if (!file) {
            alert("Please select a file.");
            return;
        }

        const reader = new FileReader();

        reader.onload = function(event) {
            const text = event.target.result;
            // Parse CSV here
            const data = parseCSV(text);
            displayCSV(data);
        };

        reader.onerror = function() {
            alert("Unable to read " + file.fileName);
        };

        reader.readAsText(file);
    });

/**
 * Parses a CSV string into an array of objects.
 * Assumes the first line contains headers.
 * @param {string} str - The CSV string.
 * @returns {Array<Object>} - The parsed data.
 */
function parseCSV(str) {
    const rows = str.split('\n');
    const headers = rows[0].split(',').map(header => header.trim());

    const data = rows.slice(1).map(row => {
        const values = row.split(',').map(value => value.trim());
        let obj = {};
        headers.forEach((header, index) => {
            obj[header] = values[index];
        });
        return obj;
    });

    return data;
}

/**
 * Displays the parsed CSV data in a table.
 * @param {Array<Object>} data - The parsed CSV data.
 */
function displayCSV(data) {
    if (data.length === 0) {
        document.getElementById('csvDisplayArea').innerHTML = "<p>No data to display.</p>";
        return;
    }

    let table = '<table><thead><tr>';

    // Create table headers
    Object.keys(data[0]).forEach(header => {
        table += `<th>${header}</th>`;
    });
    table += '</tr></thead><tbody>';

    // Create table rows
    data.forEach(row => {
        table += '<tr>';
        Object.values(row).forEach(cell => {
            table += `<td>${cell}</td>`;
        });
        table += '</tr>';
    });

    table += '</tbody></table>';

    document.getElementById('csvDisplayArea').innerHTML = table;
}
```

**Explanation:**

1. **Event Listener for File Input:**

   ```javascript
   document.getElementById('csvFileInput')
       .addEventListener('change', function (e) {
           // ...
       });
   ```

   - This attaches an event listener to the file input element.
   - The `change` event fires when a user selects a file.

2. **Handling File Selection:**

   ```javascript
