            }

            audioRecord.stop()
            audioRecord.release()
            audioTrack.stop()
            audioTrack.release()
            reverbProcessor.releaseReverb(reverbHandle)
        }.start()
    }

    private fun stopRecording() {
        isRecording = false
    }
