### 2. **Creating Controllers**

Implement controllers to handle SCIM operations.

#### **src/Controllers/UserController.php**

```php
<?php
namespace App\Controllers;

use Psr\Http\Message\ResponseInterface as Response;
use Psr\Http\Message\ServerRequestInterface as Request;
use App\Models\User;
use Ramsey\Uuid\Uuid;

class UserController
{
    protected $logger;
    public function __construct($container)
    {
        $this->logger = $container->get('logger');
    }

    // List Users
    public function listUsers(Request $request, Response $response, $args)
    {
        // Handle query parameters for filtering, pagination, etc.
        $queryParams = $request->getQueryParams();
        $users = User::all();

        $result = [
            'totalResults' => $users->count(),
            'Resources' => $users,
        ];

        $payload = json_encode($result);
        $response->getBody()->write($payload);
        return $response->withHeader('Content-Type', 'application/scim+json');
    }

    // Create User
    public function createUser(Request $request, Response $response, $args)
    {
        $data = json_decode($request->getBody(), true);

        // Validate required fields (e.g., userName)
        if (!isset($data['userName'])) {
            return $this->errorResponse($response, 400, 'userName is required');
        }

        // Create UUID for user
        $data['id'] = Uuid::uuid4()->toString();

        // Save user
        $user = User::create($data);

        $payload = json_encode($user);
        $response->getBody()->write($payload);
        return $response->withStatus(201)
                        ->withHeader('Content-Type', 'application/scim+json');
    }

    // Get User
    public function getUser(Request $request, Response $response, $args)
    {
        $id = $args['id'];
        $user = User::find($id);

        if (!$user) {
            return $this->errorResponse($response, 404, 'User not found');
        }

        $payload = json_encode($user);
        $response->getBody()->write($payload);
        return $response->withHeader('Content-Type', 'application/scim+json');
    }

    // Update User (PUT)
    public function updateUser(Request $request, Response $response, $args)
    {
        $id = $args['id'];
        $data = json_decode($request->getBody(), true);
        $user = User::find($id);

        if (!$user) {
            return $this->errorResponse($response, 404, 'User not found');
        }

        // Replace all attributes
        $user->fill($data);
        $user->save();

        $payload = json_encode($user);
        $response->getBody()->write($payload);
        return $response->withHeader('Content-Type', 'application/scim+json');
    }

    // Patch User
    public function patchUser(Request $request, Response $response, $args)
    {
        // Implement PATCH as per SCIM spec (partial updates)
        // This can be complex; consider using a library or implementing a JSON Patch parser
        // For simplicity, treat it similar to PUT
        return $this->updateUser($request, $response, $args);
    }

    // Delete User
    public function deleteUser(Request $request, Response $response, $args)
    {
        $id = $args['id'];
        $user = User::find($id);

        if (!$user) {
            return $this->errorResponse($response, 404, 'User not found');
        }

        $user->delete();

        return $response->withStatus(204);
    }

    // Helper for error responses
    private function errorResponse(Response $response, $status, $detail)
    {
        $error = [
            'schemas' => ['urn:ietf:params:scim:api:messages:2.0:Error'],
            'status' => (string)$status,
            'detail' => $detail,
        ];

        $payload = json_encode($error);
        $response->getBody()->write($payload);
        return $response->withStatus($status)
                        ->withHeader('Content-Type', 'application/scim+json');
    }
}
```

**Note:** For brevity, the above controller implements basic CRUD operations for users. You should enhance error handling, validation, and implement proper PATCH semantics as per the SCIM specification.

