   ```

2. **Initialize npm and Install Dependencies:**

   ```bash
   npm init -y
   npm install express pg cors dotenv
   ```

   - **express**: Web framework for Node.js
   - **pg**: PostgreSQL client for Node.js
   - **cors**: Middleware to enable Cross-Origin Resource Sharing
   - **dotenv**: Loads environment variables from a `.env` file

3. **Create a `.env` File:**

   Create a `.env` file in the `backend` directory to store your database credentials.

   ```env
   PORT=5000
   DB_USER=your_db_username
   DB_PASSWORD=your_db_password
   DB_HOST=localhost
   DB_PORT=5432
   DB_DATABASE=pern_todo
   ```

   > **Note:** Replace `your_db_username` and `your_db_password` with your actual PostgreSQL credentials.

### b. Set Up the Database

1. **Create the Database and Table:**

   Open your PostgreSQL client (like `psql`) and run the following commands:

   ```sql
   -- Connect to PostgreSQL
   psql -U your_db_username

   -- Create the database
   CREATE DATABASE pern_todo;

   -- Connect to the database
   \c pern_todo

   -- Create the todos table
   CREATE TABLE todos (
       id SERIAL PRIMARY KEY,
       title VARCHAR(255) NOT NULL,
       completed BOOLEAN DEFAULT FALSE
   );
   ```

### c. Create the Express Server

1. **Create `index.js` in the `backend` Directory:**

   ```javascript
   // backend/index.js
   const express = require('express');
   const cors = require('cors');
   const { Pool } = require('pg');
   require('dotenv').config();

   const app = express();
   const port = process.env.PORT || 5000;

   // Middleware
   app.use(cors());
   app.use(express.json());

   // PostgreSQL Pool Setup
   const pool = new Pool({
       user: process.env.DB_USER,
       host: process.env.DB_HOST,
       database: process.env.DB_DATABASE,
       password: process.env.DB_PASSWORD,
       port: process.env.DB_PORT,
   });

   // Routes

   // Get all todos
   app.get('/api/todos', async (req, res) => {
       try {
           const result = await pool.query('SELECT * FROM todos ORDER BY id ASC');
           res.json(result.rows);
       } catch (err) {
           console.error(err.message);
           res.status(500).send('Server error');
       }
   });

   // Create a new todo
   app.post('/api/todos', async (req, res) => {
       try {
           const { title } = req.body;
           const result = await pool.query(
               'INSERT INTO todos (title) VALUES ($1) RETURNING *',
               [title]
           );
           res.json(result.rows[0]);
       } catch (err) {
           console.error(err.message);
           res.status(500).send('Server error');
       }
   });

   // Update a todo
   app.put('/api/todos/:id', async (req, res) => {
       try {
           const { id } = req.params;
           const { title, completed } = req.body;
           const result = await pool.query(
               'UPDATE todos SET title = $1, completed = $2 WHERE id = $3 RETURNING *',
               [title, completed, id]
           );
           if (result.rows.length === 0) {
               return res.status(404).json({ message: 'Todo not found' });
           }
           res.json(result.rows[0]);
       } catch (err) {
           console.error(err.message);
           res.status(500).send('Server error');
       }
   });

   // Delete a todo
   app.delete('/api/todos/:id', async (req, res) => {
       try {
           const { id } = req.params;
           const result = await pool.query('DELETE FROM todos WHERE id = $1 RETURNING *', [id]);
           if (result.rows.length === 0) {
               return res.status(404).json({ message: 'Todo not found' });
           }
           res.json({ message: 'Todo deleted' });
       } catch (err) {
           console.error(err.message);
           res.status(500).send('Server error');
       }
   });

   // Start the server
   app.listen(port, () => {
       console.log(`Server is running on port ${port}`);
   });
   ```

2. **Add a Start Script to `package.json`:**

   ```json
