### b. Create React Components

1. **Update `App.js`:**

   ```javascript
   // frontend/src/App.js
   import React, { useState, useEffect } from 'react';
   import axios from 'axios';
   import TodoList from './components/TodoList';

   function App() {
       const [todos, setTodos] = useState([]);
       const [newTodo, setNewTodo] = useState('');

       useEffect(() => {
           fetchTodos();
       }, []);

       const fetchTodos = async () => {
           try {
               const res = await axios.get('http://localhost:5000/api/todos');
               setTodos(res.data);
           } catch (err) {
               console.error(err);
           }
       };

       const addTodo = async (e) => {
           e.preventDefault();
           if (!newTodo.trim()) return;
           try {
               const res = await axios.post('http://localhost:5000/api/todos', { title: newTodo });
               setTodos([...todos, res.data]);
               setNewTodo('');
           } catch (err) {
               console.error(err);
           }
       };

       const updateTodo = async (id, updatedTodo) => {
           try {
               const res = await axios.put(`http://localhost:5000/api/todos/${id}`, updatedTodo);
               setTodos(todos.map(todo => (todo.id === id ? res.data : todo)));
           } catch (err) {
               console.error(err);
           }
       };

       const deleteTodo = async (id) => {
           try {
               await axios.delete(`http://localhost:5000/api/todos/${id}`);
               setTodos(todos.filter(todo => todo.id !== id));
           } catch (err) {
               console.error(err);
           }
       };

       return (
           <div className="container">
               <h1>PERN To-Do List</h1>
               <form onSubmit={addTodo}>
                   <input
                       type="text"
                       value={newTodo}
                       onChange={(e) => setNewTodo(e.target.value)}
                       placeholder="Add a new todo"
                   />
                   <button type="submit">Add</button>
               </form>
               <TodoList todos={todos} updateTodo={updateTodo} deleteTodo={deleteTodo} />
           </div>
       );
   }

   export default App;
   ```

2. **Create `TodoList.js` Component:**

   ```javascript
