   import TodoItem from './TodoItem';

   const TodoList = ({ todos, updateTodo, deleteTodo }) => {
       return (
           <ul>
               {todos.map(todo => (
                   <TodoItem key={todo.id} todo={todo} updateTodo={updateTodo} deleteTodo={deleteTodo} />
               ))}
