   export default TodoList;
   ```

3. **Create `TodoItem.js` Component:**

   ```javascript
   // frontend/src/components/TodoItem.js
   import React, { useState } from 'react';

   const TodoItem = ({ todo, updateTodo, deleteTodo }) => {
       const [isEditing, setIsEditing] = useState(false);
       const [updatedTitle, setUpdatedTitle] = useState(todo.title);

       const handleToggle = () => {
           updateTodo(todo.id, { ...todo, completed: !todo.completed });
       };

       const handleEdit = (e) => {
           e.preventDefault();
           if (!updatedTitle.trim()) return;
           updateTodo(todo.id, { ...todo, title: updatedTitle });
           setIsEditing(false);
       };

       return (
           <li style={{ textDecoration: todo.completed ? 'line-through' : 'none' }}>
               <input type="checkbox" checked={todo.completed} onChange={handleToggle} />
               {isEditing ? (
                   <form onSubmit={handleEdit} style={{ display: 'inline' }}>
                       <input
                           type="text"
                           value={updatedTitle}
                           onChange={(e) => setUpdatedTitle(e.target.value)}
                       />
                       <button type="submit">Save</button>
                   </form>
               ) : (
                   <>
                       <span onDoubleClick={() => setIsEditing(true)}>{todo.title}</span>
                       <button onClick={() => deleteTodo(todo.id)}>Delete</button>
                   </>
               )}
           </li>
       );
   };

   export default TodoItem;
   ```

