```

### Explanation:

- **Sidebar**: Contains controls for uploading sprites, listing existing sprites, and deleting selected sprites.
- **Canvas Container**: Holds the HTML5 canvas where sprites are rendered and manipulated.
- **Styles**: Basic styling for layout and user interface elements.

## 2. JavaScript Functionality

Create a `sprite-editor.js` file with the following content:

```javascript
// Select DOM elements
const canvas = document.getElementById('editor-canvas');
const ctx = canvas.getContext('2d');
const spriteUpload = document.getElementById('sprite-upload');
const spriteList = document.getElementById('sprite-list');
const deleteButton = document.getElementById('delete-sprite');

// Sprite class
class Sprite {
    constructor(image, x, y) {
        this.image = image;
        this.x = x; // Position
        this.y = y;
        this.scale = 1;
        this.rotation = 0; // in radians
        this.width = image.width;
        this.height = image.height;
        // For dragging
        this.isDragging = false;
        this.offsetX = 0;
        this.offsetY = 0;
    }

    draw(ctx) {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(this.rotation);
        ctx.scale(this.scale, this.scale);
        ctx.drawImage(this.image, -this.width / 2, -this.height / 2);
        ctx.restore();
    }

    isPointInside(px, py) {
        // Simple bounding box collision
        const left = this.x - (this.width * this.scale) / 2;
        const right = this.x + (this.width * this.scale) / 2;
        const top = this.y - (this.height * this.scale) / 2;
        const bottom = this.y + (this.height * this.scale) / 2;
        return px >= left && px <= right && py >= top && py <= bottom;
    }
}

// Application state
let sprites = [];
let selectedSprite = null;
let isDragging = false;

// Handle Sprite Upload
spriteUpload.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function(event) {
        const img = new Image();
        img.onload = function() {
            const sprite = new Sprite(img, canvas.width / 2, canvas.height / 2);
            sprites.push(sprite);
            addSpriteToList(sprite);
            draw();
        }
        img.src = event.target.result;
    }
    reader.readAsDataURL(file);
    // Reset the input
    spriteUpload.value = '';
});

// Add sprite to the sidebar list
function addSpriteToList(sprite) {
    const li = document.createElement('li');
    li.textContent = `Sprite ${sprites.length}`;
    li.addEventListener('click', () => {
        selectSprite(sprite, li);
    });
    sprite.element = li;
    spriteList.appendChild(li);
}

// Select a sprite
function selectSprite(sprite, listItem) {
    if (selectedSprite && selectedSprite.element) {
        selectedSprite.element.classList.remove('selected');
    }
    selectedSprite = sprite;
    if (selectedSprite && selectedSprite.element) {
        selectedSprite.element.classList.add('selected');
    }
}

// Delete selected sprite
deleteButton.addEventListener('click', () => {
    if (!selectedSprite) return;
    const index = sprites.indexOf(selectedSprite);
    if (index > -1) {
        // Remove from array
        sprites.splice(index, 1);
        // Remove from list
        spriteList.removeChild(selectedSprite.element);
        selectedSprite = null;
        draw();
    }
});

// Mouse interactions
canvas.addEventListener('mousedown', (e) => {
    const mousePos = getMousePos(e);
    for (let i = sprites.length - 1; i >= 0; i--) { // Top-down
        if (sprites[i].isPointInside(mousePos.x, mousePos.y)) {
            selectedSprite = sprites[i];
            selectSprite(sprites[i], sprites[i].element);
            isDragging = true;
            sprites[i].offsetX = mousePos.x - sprites[i].x;
            sprites[i].offsetY = mousePos.y - sprites[i].y;
            draw();
            return;
        }
    }
    // Clicked on empty space
    if (selectedSprite && selectedSprite.element) {
        selectedSprite.element.classList.remove('selected');
    }
    selectedSprite = null;
    draw();
});

canvas.addEventListener('mousemove', (e) => {
    if (!isDragging || !selectedSprite) return;
    const mousePos = getMousePos(e);
    selectedSprite.x = mousePos.x - selectedSprite.offsetX;
    selectedSprite.y = mousePos.y - selectedSprite.offsetY;
    draw();
});

canvas.addEventListener('mouseup', () => {
    isDragging = false;
});

canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    if (!selectedSprite) return;
    const delta = e.deltaY > 0 ? -0.05 : 0.05;
    selectedSprite.scale = Math.min(Math.max(selectedSprite.scale + delta, 0.1), 3);
    draw();
});

// Utility to get mouse position
function getMousePos(evt) {
    const rect = canvas.getBoundingClientRect();
    return {
        x: (evt.clientX - rect.left) * (canvas.width / rect.width),
        y: (evt.clientY - rect.top) * (canvas.height / rect.height)
    };
}

// Render the canvas
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    sprites.forEach(sprite => {
        sprite.draw(ctx);
    });
    // Optionally, highlight selected sprite
    if (selectedSprite) {
        ctx.save();
        ctx.strokeStyle = 'red';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.rect(
            selectedSprite.x - (selectedSprite.width * selectedSprite.scale) / 2,
            selectedSprite.y - (selectedSprite.height * selectedSprite.scale) / 2,
            selectedSprite.width * selectedSprite.scale,
            selectedSprite.height * selectedSprite.scale
        );
        ctx.stroke();
        ctx.restore();
    }
}

// Initial draw
draw();
```

### Explanation:

1. **Sprite Class**: Represents each sprite with properties like position (`x`, `y`), scale, rotation, and methods to draw itself and detect if a point is inside its boundaries.

2. **Application State**:
    - `sprites`: An array to hold all sprite instances.
    - `selectedSprite`: Currently selected sprite for manipulation.
    - `isDragging`: Flag to indicate if a sprite is being dragged.

3. **Sprite Upload**:
    - Handles the uploading of images.
    - Creates a new `Sprite` instance for each uploaded image and adds it to the sprites array and the sidebar list.

4. **Sprite List**:
    - Displays all sprites in the sidebar.
    - Allows selection of a sprite by clicking on its list item.
    - Applies a "selected" class for visual feedback.

5. **Delete Functionality**:
    - Allows deletion of the currently selected sprite.

6. **Mouse Interactions**:
    - **mousedown**: Selects a sprite if clicked on and starts dragging.
    - **mousemove**: Updates the sprite's position if dragging.
    - **mouseup**: Stops dragging.
    - **wheel**: Zooms in/out on the selected sprite by adjusting its scale.

7. **Rendering**:
    - The `draw` function clears the canvas and redraws all sprites.
    - Highlights the selected sprite with a red rectangle.

8. **Utility Functions**:
    - `getMousePos`: Calculates the mouse position relative to the canvas.

## 3. Usage

1. **Setup**:
    - Ensure both `index.html` and `sprite-editor.js` are in the same directory.
    - Open `index.html` in a web browser.

2. **Adding Sprites**:
    - Click on the "Add Sprite" button and select an image file from your computer.
    - The sprite will appear in the center of the canvas and listed in the sidebar.

3. **Selecting Sprites**:
    - Click on a sprite from the sidebar list or directly on the canvas to select it.
    - The selected sprite is highlighted with a red border.

4. **Manipulating Sprites**:
    - **Move**: Click and drag the sprite on the canvas.
    - **Scale**: Use the mouse wheel while the sprite is selected to scale it up or down.

5. **Deleting Sprites**:
    - Select a sprite and click the "Delete Selected Sprite" button to remove it.

## 4. Enhancements

This basic sprite editor can be enhanced with additional features such as:

- **Rotation Control**: Provide UI controls (like a slider) to rotate the sprite.
- **Layer Management**: Allow changing the z-order of sprites.
- **Save/Load Functionality**: Enable saving the current sprite layout and loading it later.
- **Multiple Selection**: Allow selecting and manipulating multiple sprites simultaneously.
- **Better Collision Detection**: Implement more accurate hit detection considering rotation and scale.

## 5. Libraries

For more advanced functionalities and better performance, consider using libraries such as [Fabric.js](http://fabricjs.com/) or [Konva.js](https://konvajs.org/). These libraries provide powerful tools for canvas manipulation and can simplify the development of complex sprite editors.

### Example with Fabric.js

If you prefer leveraging a library to handle more complex interactions, here's a brief example using Fabric.js:

1. **Include Fabric.js**:

```html
<script src="https://cdnjs.cloudflare.com/ajax/libs/fabric.js/4.6.0/fabric.min.js"></script>
```

2. **Initialize Fabric Canvas**:

```javascript
const fabricCanvas = new fabric.Canvas('editor-canvas');

// Handle sprite upload
spriteUpload.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function(event) {
        fabric.Image.fromURL(event.target.result, function(img) {
            img.set({
                left: fabricCanvas.width / 2,
                top: fabricCanvas.height / 2,
                originX: 'center',
                originY: 'center',
                selectable: true
            });
            fabricCanvas.add(img);
            fabricCanvas.setActiveObject(img);
        });
    }
    reader.readAsDataURL(file);
    spriteUpload.value = '';
});
```

Fabric.js handles interactions like dragging, scaling, and rotating out of the box, reducing the amount of code you need to write.

## Conclusion

The above implementation provides a foundational sprite editor where you can add, select, move, scale, and delete sprites. Depending on your needs, you can expand this editor with more sophisticated features and better user experience. Leveraging libraries like Fabric.js can accelerate development and add robustness to your editor.

To integrate `@tanstack/vue-query` with a global Pinia store for fetching data from the `/get_session` endpoint and selectively updating the store, follow these steps:

1. **Set Up Your Project**

   Ensure you have the necessary packages installed:

   ```bash
   npm install @tanstack/vue-query pinia axios
   ```

2. **Initialize Pinia**

   Set up Pinia in your main application file (e.g., `main.js` or `main.ts`):

   ```javascript
   // main.js
   import { createApp } from 'vue'
   import { createPinia } from 'pinia'
   import { VueQueryPlugin } from '@tanstack/vue-query'
   import App from './App.vue'

   const app = createApp(App)
   const pinia = createPinia()

   app.use(pinia)
   app.use(VueQueryPlugin)

   app.mount('#app')
   ```

3. **Create a Pinia Store**

   Define a Pinia store that will hold the session data. For example, create a store named `useSessionStore.js`:

   ```javascript
   // stores/useSessionStore.js
   import { defineStore } from 'pinia'

   export const useSessionStore = defineStore('session', {
     state: () => ({
       userId: null,
       token: null,
       // Add other keys you want to store
     }),
     actions: {
       setSession(data) {
         this.userId = data.userId
         this.token = data.token
         // Set other keys as needed
       },
       clearSession() {
         this.userId = null
         this.token = null
         // Clear other keys as needed
       },
     },
   })
   ```

4. **Set Up the Vue Query to Fetch and Select Data**

   Create a composable or directly use `useQuery` within your component to fetch data from `/get_session`. Use the `select` option to extract specific keys from the response.

   ```javascript
   // composables/useSession.js
   import { useQuery } from '@tanstack/vue-query'
   import axios from 'axios'
   import { useSessionStore } from '@/stores/useSessionStore'

   export function useSession() {
     const sessionStore = useSessionStore()

     const fetchSession = async () => {
       const response = await axios.get('/get_session')
       return response.data
     }

     const { data, error, isLoading } = useQuery(
       ['session'],
       fetchSession,
       {
         select: (data) => {
           // Select specific keys from the response
           return {
             userId: data.user_id,
             token: data.auth_token,
             // Add other keys as needed
           }
         },
         onSuccess: (selectedData) => {
           // Update the Pinia store with the selected data
           sessionStore.setSession(selectedData)
         },
         onError: (err) => {
           console.error('Error fetching session:', err)
           // Optionally, handle errors, e.g., clear the store
           sessionStore.clearSession()
         },
       }
     )

     return {
       data,
       error,
       isLoading,
     }
   }
   ```

5. **Use the Composable in Your Component**

   Now, in any component where you need to fetch and store the session data, use the `useSession` composable.

   ```vue
   <!-- components/SessionComponent.vue -->
   <template>
     <div>
       <div v-if="isLoading">Loading session...</div>
       <div v-else-if="error">Error loading session: {{ error.message }}</div>
       <div v-else>
         <p>User ID: {{ sessionStore.userId }}</p>
         <p>Token: {{ sessionStore.token }}</p>
       </div>
     </div>
   </template>

   <script setup>
   import { useSession } from '@/composables/useSession'
   import { useSessionStore } from '@/stores/useSessionStore'

   const { data, error, isLoading } = useSession()
   const sessionStore = useSessionStore()
   </script>
   ```

   **Explanation:**

   - **Template Section:**
     - Displays a loading message while the data is being fetched.
     - Shows an error message if the fetch fails.
     - Once data is successfully fetched, it displays the `userId` and `token` from the Pinia store.

   - **Script Section:**
     - Calls the `useSession` composable to initiate the data fetching.
     - Accesses the `sessionStore` to read the stored session data.

6. **Handling Authentication State Globally**

   If you want the session to be fetched and stored as soon as the application loads, you can place the `useSession` composable in a root component like `App.vue` or in a layout component.

   ```vue
   <!-- App.vue -->
   <template>
     <router-view />
   </template>

   <script setup>
   import { useSession } from '@/composables/useSession'

   // Initiate session fetching on app load
   useSession()
   </script>
   ```

7. **Advanced: Automatically Refetch or Handle Session Expiry**

   Depending on your application needs, you can configure vue-query to refetch the session data at specified intervals or when certain events occur.

   ```javascript
   // In composables/useSession.js

   const { data, error, isLoading } = useQuery(
     ['session'],
     fetchSession,
     {
       select: (data) => ({
         userId: data.user_id,
         token: data.auth_token,
       }),
       onSuccess: (selectedData) => {
         sessionStore.setSession(selectedData)
       },
       onError: (err) => {
         console.error('Error fetching session:', err)
         sessionStore.clearSession()
       },
       // Refetch the session every 5 minutes
       refetchInterval: 300000, // 300,000 ms = 5 minutes
       // Refetch on window focus
       refetchOnWindowFocus: true,
     }
   )
   ```

8. **Security Considerations**

   - **Protecting Sensitive Data:** Ensure that sensitive information like tokens are handled securely. Avoid exposing them in the frontend if possible.
   - **Error Handling:** Properly handle errors, such as invalid or expired tokens, and implement logout or token refresh mechanisms as needed.
   - **Caching:** Configure vue-query’s caching strategies according to your security requirements.

9. **Full Example**

   Here's a consolidated example combining all the steps:

   **Store:**

   ```javascript
   // stores/useSessionStore.js
   import { defineStore } from 'pinia'

   export const useSessionStore = defineStore('session', {
     state: () => ({
       userId: null,
       token: null,
     }),
     actions: {
       setSession(data) {
         this.userId = data.userId
         this.token = data.token
       },
       clearSession() {
         this.userId = null
         this.token = null
       },
     },
   })
   ```

   **Composable:**

   ```javascript
   // composables/useSession.js
   import { useQuery } from '@tanstack/vue-query'
   import axios from 'axios'
   import { useSessionStore } from '@/stores/useSessionStore'

   export function useSession() {
     const sessionStore = useSessionStore()

     const fetchSession = async () => {
       const response = await axios.get('/get_session')
       return response.data
     }

     const query = useQuery(
       ['session'],
       fetchSession,
       {
         select: (data) => ({
           userId: data.user_id,
           token: data.auth_token,
         }),
         onSuccess: (data) => {
           sessionStore.setSession(data)
         },
         onError: (error) => {
           console.error('Failed to fetch session:', error)
           sessionStore.clearSession()
         },
         refetchOnWindowFocus: true,
         refetchInterval: 300000, // 5 minutes
       }
     )

     return {
       ...query,
       session: sessionStore,
     }
   }
   ```

   **Component:**

   ```vue
   <!-- components/SessionComponent.vue -->
   <template>
     <div>
       <div v-if="isLoading">Loading session...</div>
       <div v-else-if="error">Error: {{ error.message }}</div>
       <div v-else>
         <p>User ID: {{ session.userId }}</p>
         <p>Token: {{ session.token }}</p>
       </div>
     </div>
   </template>

   <script setup>
   import { useSession } from '@/composables/useSession'

   const { isLoading, error, session } = useSession()
   </script>
   ```

   **Main App:**

   ```vue
   <!-- App.vue -->
   <template>
     <SessionComponent />
     <router-view />
   </template>

   <script setup>
   import SessionComponent from '@/components/SessionComponent.vue'
   import { useSession } from '@/composables/useSession'

   // Fetch session on app load
   useSession()
   </script>
   ```

**Summary:**

1. **Pinia Store:** Define a global store to hold the session data with actions to set and clear the data.
2. **Vue Query:** Use `useQuery` to fetch data from `/get_session`, selecting only the required keys.
3. **Integration:** On successful fetch, update the Pinia store with the selected data.
4. **Usage:** Access the store in your components to utilize the session data.

This setup ensures that your session data is fetched efficiently, transformed as needed, and made globally accessible through Pinia.

